package workerpool

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"sync/atomic"
)

// Pool is a fixed-size worker pool that executes submitted functions.
type Pool struct {
	n        int
	tasks    chan func() error
	errCh    chan error
	wg       sync.WaitGroup
	mu       sync.Mutex
	shutdown bool
	panics   []any
}

// New creates a new Pool with n workers.
func New(n int) *Pool {
	if n <= 0 {
		n = 1
	}
	p := &Pool{
		n:     n,
		tasks: make(chan func() error),
		errCh: make(chan error, n),
	}
	for i := 0; i < n; i++ {
		p.wg.Add(1)
		go p.worker()
	}
	return p
}

// worker runs the main loop for a single worker goroutine.
func (p *Pool) worker() {
	defer p.wg.Done()
	for task := range p.tasks {
		p.execute(task)
	}
}

// execute runs a single task, recovering from panics and collecting errors.
func (p *Pool) execute(task func() error) {
	defer func() {
		if r := recover(); r != nil {
			p.mu.Lock()
			p.panics = append(p.panics, r)
			p.mu.Unlock()
			// Send a panic error to the error channel so callers can observe it.
			select {
			case p.errCh <- fmt.Errorf("panic in worker: %v", r):
			default:
				// Drop if channel is full; the panic is still recorded in p.panics.
			}
		}
	}()
	if err := task(); err != nil {
		select {
		case p.errCh <- err:
		default:
			// Drop if channel is full.
		}
	}
}

// Submit enqueues a function for execution. It returns an error if the pool
// has been shut down.
func (p *Pool) Submit(fn func() error) error {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.shutdown {
		return errors.New("pool is shut down")
	}
	p.tasks <- fn
	return nil
}

// Errors returns the channel on which task errors are delivered.
func (p *Pool) Errors() <-chan error {
	return p.errCh
}

// Panics returns a copy of all recovered panics so far.
func (p *Pool) Panics() []any {
	p.mu.Lock()
	defer p.mu.Unlock()
	out := make([]any, len(p.panics))
	copy(out, p.panics)
	return out
}

